# 遗传模拟：Aa x Aa 生 100 个娃
aa = 0
has_A = 0
for kid in range(100):
    dad = random(1, 2)      # 1=A, 2=a
    mom = random(1, 2)
    if dad == 2:
        if mom == 2:
            aa = aa + 1     # 隐性纯合：单眼皮
        else:
            has_A = has_A + 1
    else:
        has_A = has_A + 1

say("单眼皮 aa 约 " + aa + " 个（理论 25）")
say("双眼皮 约 " + has_A + " 个（理论 75）")
say("比例接近 3:1 —— 孟德尔分离定律！")
